    c.font = "bold 34px Arial";
    c.fillText(String(Math.round(kmh)), 52, 50);
    c.font = "12px Arial";
    c.fillStyle = "#6fa7c0";
    c.fillText("km/h", 52, 70);
    c.fillStyle = "#ffd36b";
    c.font = "bold 30px Arial";
    c.fillText(String(Math.round(agl)), 140, 50);
    c.font = "12px Arial";
    c.fillStyle = "#6fa7c0";
    c.fillText("m dal suolo", 140, 70);
    c.fillStyle = vs >= 0 ? "#7dff9a" : "#ffb36b";
