      let dh = a.h - v.h;
      while (dh > Math.PI) dh -= 2 * Math.PI;
      while (dh < -Math.PI) dh += 2 * Math.PI;
      const w = dt > 0 ? dh / dt : 0, acc = dt > 0 ? (a.speed - v.u) / dt : 0;
      v.x = a.x;
      v.z = a.z;
      v.y = a.y;
      v.h = a.h;
      v.v = 0;
      v.w = w;
      v.airborne = false;
      v.u = a.speed;
      const st = a.speed > 0.8 ? Math.atan(v.L * w / a.speed) : v.steer;
      v.steer += (Math.max(-0.6, Math.min(0.6, st)) - v.steer) * Math.min(1, dt * 6);
