      if (!hasRunner && (!this.enabled || G5.foot.on && !this.heat)) {
        for (const c of this.cars) this.place(c, now2);
        if (!this.enabled && G5.audio && G5.audio.siren) G5.audio.siren(0);
        return;
      }
      const pv = G5.vehicle, px2 = p.x, pz2 = p.z;
      const pursuit = this.enabled && this.heat >= 1;
      this.matchPlayer(pv);
      const want = pursuit ? [0, 2, 3, 4, 5, 6][this.stars] : 2;
      const active = this.cars.filter((c) => c.mode !== "block" && c.mode !== "runner" && c.mode !== "caught");
      this.spawnT -= dt;
      if (this.enabled && active.length < want && this.spawnT <= 0) {
        const sp = this.spawnPoint(p, pursuit ? 170 + Math.random() * 110 : 300 + Math.random() * 200, true, pursuit);
        if (sp) {
          const c = this.makeCar(sp.x, sp.z, sp.h);
          c.mode = pursuit ? "pursuit" : "patrol";
          if (!pursuit && !this.toLane(c, 1e9)) this.remove(c);
        }
        this.spawnT = pursuit ? 3 : 6;
      }
