    G4.settings.farKm = (QUALITY[$("quality").value] || QUALITY.mid).farKm;
    G4.settings.detailKm = (QUALITY[$("quality").value] || QUALITY.mid).detailKm;
    G4.settings.detailDist = (QUALITY[$("quality").value] || QUALITY.mid).detailDist;
    if (G4.settings.farKm > 0) G4.world.initFar();
    G4.traffic.target = +$("traffic").value;
    $("ptraffic").value = $("traffic").value;
    G4.sky.hours = +$("tod").value;
